values
  ('459d8c92-a66c-4afa-9e9a-a4e95f8950a6', 'c9d2f5b8-3a6e-4c17-8f42-7b1c6d9a8e25', null, 'topic'::public.curated_course_node_type, 'Quantitative Reasoning and Business Model Building', 'Introduces the disciplined translation of an ambiguous business question into variables, relationships, assumptions, and decision criteria. The goal is not merely to calculate, but to construct models that are useful, auditable, and appropriately limited.', 0),
  ('9044fced-c474-4f94-b71e-21458062251d', 'c9d2f5b8-3a6e-4c17-8f42-7b1c6d9a8e25', '459d8c92-a66c-4afa-9e9a-a4e95f8950a6', 'subtopic'::public.curated_course_node_type, 'From decisions to models', 'Learn to frame a managerial decision before choosing mathematics.', 0),
