update public.learning_paths
set
  title = 'Calculus / Quantitative Methods',
  goal = 'Calculus / Quantitative Methods',
  summary = 'This course develops the mathematical judgment required to formulate, solve, test, and communicate business models. Students use functions, derivatives, integrals, multivariable calculus, matrices, and optimization to analyze pricing, profit, growth, allocation, capacity, and risk.',
  data = $cqmjson${"slug": "calculus-quantitative-methods", "title": "Calculus / Quantitative Methods", "description": "This course develops the mathematical judgment required to formulate, solve, test, and communicate business models. Students use functions, derivatives, integrals, multivariable calculus, matrices, and optimization to analyze pricing, profit, growth, allocation, capacity, and risk.", "topics": [{"id": "459d8c92-a66c-4afa-9e9a-a4e95f8950a6", "type": "topic", "title": "Quantitative Reasoning and Business Model Building", "description": "Introduces the disciplined translation of an ambiguous business question into variables, relationships, assumptions, and decision criteria. The goal is not merely to calculate, but to construct models that are useful, auditable, and appropriately limited.", "children": [{"id": "9044fced-c474-4f94-b71e-21458062251d", "type": "subtopic", "title": "From decisions to models", "children": [{"id": "43e54ea5-e1cd-41f2-8e8e-e956e8bbd01e", "type": "concept", "title": "Decision variables, objectives, constraints, and stakeholders"}, {"id": "8611ca03-82e9-49c6-a030-45a2236feb85", "type": "concept", "title": "Inputs, outputs, parameters, and controllable versus uncontrollable factors"}, {"id": "ad18feab-ccd4-485d-a161-c37c44b0841e", "type": "concept", "title": "Descriptive, predictive, and prescriptive questions"}], "description": "Learn to frame a managerial decision before choosing mathematics."}, {"id": "e0c591f7-1af4-4c78-a72a-1614d397e6a6", "type": "subtopic", "title": "Units, scale, and dimensional reasoning", "children": [{"id": "7d85d7ad-690d-4d6c-927f-c43a88aa0408", "type": "concept", "title": "Rates, ratios, percentages, basis points, and index numbers"}, {"id": "631ead23-d10d-49c1-8dce-ff3b9a32b364", "type": "concept", "title": "Nominal versus real quantities and currency/time conventions"}, {"id": "42e0cf00-1424-4677-bf20-da9a31deb771", "type": "concept", "title": "Dimensional consistency and order-of-magnitude checks"}], "description": "Use units to detect errors and make quantities comparable."}, {"id": "606ad981-b000-4618-8bf5-aabe4ed788bf", "type": "subtopic", "title": "Assumptions and validation", "children": [{"id": "9246cb3e-b03b-4f1e-8244-20c080487935", "type": "concept", "title": "Scope, boundary conditions, and ceteris paribus reasoning"}, {"id": "8f514ec0-145e-4c60-9bde-cb523d367133", "type": "concept", "title": "Face, internal, and external validity"}, {"id": "858f19f4-8c32-4f75-a8ca-69846a226dd1", "type": "concept", "title": "Back-testing, benchmarking, residual checks, and reasonableness tests"}], "description": "Treat every model as a conditional representation rather than reality itself."}, {"id": "f18b934e-35ac-480e-a706-b9182d921b55", "type": "subtopic", "title": "Responsible quantitative practice", "children": [{"id": "3cef64af-bdd6-4fbe-9513-18d3678b4805", "type": "concept", "title": "Data provenance, privacy, and documentation"}, {"id": "7147e651-9f24-40f0-b7b5-79d7f0d84330", "type": "concept", "title": "Proxy variables, omitted impacts, and distributional consequences"}, {"id": "8774449c-41d3-41ba-afe9-ab5d5042751d", "type": "concept", "title": "Communicating uncertainty and avoiding false precision"}], "description": "Recognize that model choices affect people, capital, and risk."}]}, {"id": "96df65ba-8c58-4714-9d74-ac1430e13009", "type": "topic", "title": "Functions and Business Relationships", "description": "Builds fluency with functions as reusable descriptions of demand, cost, revenue, profit, growth, and other relationships. Students learn to move among equations, tables, graphs, and verbal interpretations.", "children": [{"id": "2c511d61-315f-416b-a03e-5ec069611e53", "type": "subtopic", "title": "Function language", "children": [{"id": "997f0210-cc2a-4992-9090-39b1aa908883", "type": "concept", "title": "Domain, range, notation, and evaluation"}, {"id": "221288b6-4dba-4d73-a09c-99bf648d1609", "type": "concept", "title": "Independent, dependent, endogenous, and exogenous variables"}, {"id": "9eb9d579-5d46-4e06-bf2b-0334491dcc81", "type": "concept", "title": "Composition, inverse functions, and piecewise definitions"}], "description": "Represent how one or more inputs determine an output."}, {"id": "7c4c913c-4657-4295-b987-ab410632c140", "type": "subtopic", "title": "Core function families", "children": [{"id": "933d0900-2bd2-43d2-b3af-7b1c9822d498", "type": "concept", "title": "Linear and affine models"}, {"id": "3dbf54e5-edc6-4181-808b-2190bb9318c0", "type": "concept", "title": "Polynomial, rational, power, exponential, and logarithmic functions"}, {"id": "b4924f9d-154c-40ba-92a1-ba75ae80c5c0", "type": "concept", "title": "S-curves, saturation, and piecewise pricing"}], "description": "Recognize common shapes and their business meanings."}, {"id": "e56b84f4-6785-4492-8eab-bc9bfe216947", "type": "subtopic", "title": "Business model construction", "children": [{"id": "b6521b0b-54c9-4911-87e7-148a0a960a69", "type": "concept", "title": "Demand, supply, cost, revenue, and profit"}, {"id": "e5f662eb-3d31-447d-ad26-269745dcfbc7", "type": "concept", "title": "Average cost, unit economics, contribution margin, and break-even"}, {"id": "11d85eb8-3690-4f07-bd88-31301b28e08a", "type": "concept", "title": "Learning curves, network effects, and economies of scale"}], "description": "Convert contextual information into mathematical relationships."}, {"id": "9fd6eee8-6137-4f7e-b084-23b2fa000d06", "type": "subtopic", "title": "Graphical interpretation", "children": [{"id": "fe1ca00d-5e82-462b-9af3-9208018f0960", "type": "concept", "title": "Intercepts, slopes, curvature, and turning points"}, {"id": "cac9014a-0f20-4cc2-8b54-aa16a00a7e37", "type": "concept", "title": "Transformations and parameter effects"}, {"id": "a2c18326-52eb-4504-8194-f8362769dd8c", "type": "concept", "title": "Extrapolation risk and misleading axes"}], "description": "Read business consequences directly from a graph."}]}, {"id": "b5e77b13-e21f-48af-9eb7-4cc2e6ac1ff4", "type": "topic", "title": "Limits, Continuity, and Rates of Change", "description": "Develops the conceptual bridge from average change to instantaneous change. Limits make marginal reasoning precise and expose thresholds, asymptotes, and discontinuities in business systems.", "children": [{"id": "657b3c6c-f44f-4c58-8154-be0f0f3c2a28", "type": "subtopic", "title": "Average and instantaneous change", "children": [{"id": "f63c15e6-e789-4cb0-a1b8-a23f3e36a780", "type": "concept", "title": "Difference quotients and secant slopes"}, {"id": "37b28d4b-234b-44d5-910d-5c07b6b73f4b", "type": "concept", "title": "Instantaneous rate and tangent slope"}, {"id": "aec0c319-6fe7-433b-a365-c151be3fb513", "type": "concept", "title": "Absolute, relative, and percentage change"}], "description": "Understand how rates depend on the interval of measurement."}, {"id": "dff14cee-07ee-4977-abb2-14329977b6b4", "type": "subtopic", "title": "Limits", "children": [{"id": "c4db54b8-ca1c-4a12-b28f-e7527a69d55d", "type": "concept", "title": "Numerical, graphical, and algebraic limits"}, {"id": "6e6a62a5-d812-4342-8a1c-a78527f14bc2", "type": "concept", "title": "One-sided limits and infinite limits"}, {"id": "7f2dd317-980f-4646-9564-2e0cc8756e00", "type": "concept", "title": "End behavior and asymptotes"}], "description": "Reason about values approached near a point or over long horizons."}, {"id": "ef20c655-d9de-4322-b05f-bf97dc74e67c", "type": "subtopic", "title": "Continuity and discontinuity", "children": [{"id": "e2d03f76-30c4-47fd-825c-b2cdf51864c7", "type": "concept", "title": "Continuity conditions"}, {"id": "f7de28cb-a0e3-4c34-9de7-96d32d4b1b39", "type": "concept", "title": "Removable, jump, and infinite discontinuities"}, {"id": "781aba3d-3aa9-4f34-91a2-04a25456c397", "type": "concept", "title": "Tiered prices, capacity thresholds, and policy cliffs"}], "description": "Identify when small input changes do—or do not—produce small output changes."}, {"id": "159c8c5c-f7c2-4acc-a9c0-95acbaed8843", "type": "subtopic", "title": "Approximation", "children": [{"id": "c0dc93f7-4ce5-48fc-a040-df960d41dedf", "type": "concept", "title": "Linear interpolation and local linearity"}, {"id": "842b62b2-814a-49dd-a8f9-4c1f805ec8b7", "type": "concept", "title": "Error bounds and rounding"}, {"id": "be16f7bb-3f6a-4603-ba51-f7d674d944cb", "type": "concept", "title": "When approximation fails"}], "description": "Use local information for practical estimation."}]}, {"id": "b0e4d96f-dfe0-451f-bd01-7fad5aca1f95", "type": "topic", "title": "Derivatives and Differentiation", "description": "Provides the main language of marginal analysis. Students compute derivatives accurately, interpret their units, and connect first and second derivatives to movement, responsiveness, and curvature.", "children": [{"id": "5a99573d-a98c-4724-abd4-bba8a15fb131", "type": "subtopic", "title": "Derivative concepts", "children": [{"id": "2a5ded7b-ce0f-44ff-b6d4-785e5b35d86b", "type": "concept", "title": "Derivative as rate, slope, and local sensitivity"}, {"id": "f536ad2c-a8e4-48bd-8fb9-9b4bf046020a", "type": "concept", "title": "Derivative notation and units"}, {"id": "3b836af0-da49-436b-a980-5bfd1f1d8f46", "type": "concept", "title": "Differentiability versus continuity"}], "description": "Connect symbolic, graphical, and contextual meanings."}, {"id": "1cd9a22e-51d0-475c-8de9-8af5431483fe", "type": "subtopic", "title": "Differentiation rules", "children": [{"id": "2f4ab4b5-652b-419f-ae53-8ea6d1e10063", "type": "concept", "title": "Constant, power, sum, product, and quotient rules"}, {"id": "86097fb2-943c-427b-a05e-9bf69463f653", "type": "concept", "title": "Chain rule and composite business models"}, {"id": "fa8ea77b-08eb-4ded-987b-a63c6d9ea3ff", "type": "concept", "title": "Exponential and logarithmic derivatives"}], "description": "Compute derivatives efficiently for realistic functions."}, {"id": "42124276-42e7-4970-9be6-c7dbf5ef9340", "type": "subtopic", "title": "Higher derivatives and curvature", "children": [{"id": "f72d3e0f-460b-469f-8b61-2c03b812e1f5", "type": "concept", "title": "Second derivative and concavity"}, {"id": "b7c53ea4-1ec0-4811-99a2-2a19466edd4b", "type": "concept", "title": "Inflection points"}, {"id": "ae060ab9-1334-4774-a36c-4cc1cc751efb", "type": "concept", "title": "Increasing/decreasing and concave/convex behavior"}], "description": "Use changes in the marginal effect to understand acceleration and diminishing returns."}, {"id": "ed0fe845-820c-40a5-b332-637dcb8f7e38", "type": "subtopic", "title": "Numerical and spreadsheet differentiation", "children": [{"id": "c04ea7fe-2fd1-4898-865a-bb790df34742", "type": "concept", "title": "Forward, backward, and central differences"}, {"id": "1daf0b2e-3467-4025-a7eb-bea27b2b10bc", "type": "concept", "title": "Step-size and numerical error"}, {"id": "2ff36b16-8299-44fb-9c60-edcd261ecb44", "type": "concept", "title": "Spreadsheet formulas and visual verification"}], "description": "Estimate derivatives when no clean formula is available."}]}, {"id": "1d4afcdf-8a99-4dbd-864b-80afe646c698", "type": "topic", "title": "Marginal Analysis, Elasticity, and Comparative Statics", "description": "Applies derivatives to the questions business students encounter most often: the value of one more unit, responsiveness to price or income, and how an optimal outcome changes when assumptions change.", "children": [{"id": "94058532-502c-44bc-b434-35ea5275f6a9", "type": "subtopic", "title": "Marginal quantities", "children": [{"id": "bb36f1f8-d7ce-4f40-8035-2b5c9bf0f35b", "type": "concept", "title": "Marginal cost, revenue, profit, product, and utility"}, {"id": "90088cd5-9c29-43d3-99a2-6c6e4be6ad6b", "type": "concept", "title": "Average versus marginal quantities"}, {"id": "71ee4332-8dc7-4a72-9320-3606874dac55", "type": "concept", "title": "Discrete increments versus continuous approximations"}], "description": "Interpret derivatives as local economic and managerial effects."}, {"id": "fcf791f6-433e-4502-8a55-4f14e10d861d", "type": "subtopic", "title": "Elasticity", "children": [{"id": "da12b156-9772-4486-870e-2ee388e81f5d", "type": "concept", "title": "Point and arc elasticity"}, {"id": "5b756275-79bb-4426-ae13-fabaa4c24d0c", "type": "concept", "title": "Price, income, and cross-price elasticity"}, {"id": "c4a54b2b-4197-486c-837a-90283eed519e", "type": "concept", "title": "Elastic, inelastic, and unit-elastic demand"}], "description": "Measure proportional responsiveness in unit-free terms."}, {"id": "28506d35-41c0-434c-95c7-e483f3c1a719", "type": "subtopic", "title": "Comparative statics", "children": [{"id": "4d335ce3-131c-4659-a773-4a7afca79502", "type": "concept", "title": "Parameter sensitivity and implicit relationships"}, {"id": "948e09cc-4f69-486b-8b3e-81dd100705b0", "type": "concept", "title": "Pass-through, incidence, and break-even shifts"}, {"id": "8d63c95c-6ea7-405e-8df9-31621af8f5ec", "type": "concept", "title": "Local versus global conclusions"}], "description": "Study how outcomes shift when a parameter changes."}, {"id": "a5337a04-8ea4-4b5b-870b-d667ba6c758e", "type": "subtopic", "title": "Decision relevance", "children": [{"id": "e1e9882f-e43e-41a6-9672-b819fffd6770", "type": "concept", "title": "Pricing and promotion"}, {"id": "d30dbeef-c73e-4fd8-975b-6c4e2b7efb91", "type": "concept", "title": "Capacity and staffing"}, {"id": "36ba1b22-5ec7-4356-815e-018fa6c1aedd", "type": "concept", "title": "Customer acquisition and lifetime value assumptions"}], "description": "Connect marginal evidence to managerial action."}]}, {"id": "ba88152a-3683-4887-93bd-fa44e7e8352c", "type": "topic", "title": "Unconstrained Optimization and Managerial Decisions", "description": "Uses first- and second-order reasoning to identify and validate best feasible choices when constraints are implicit or captured in the objective.", "children": [{"id": "90000582-21cf-402a-aa99-feb1707c4b76", "type": "subtopic", "title": "Optimization workflow", "children": [{"id": "4e0820e1-3dfb-4fa3-96d8-9fd4efb83195", "type": "concept", "title": "Decision variable and objective"}, {"id": "0c937a13-8ee8-4e23-b5c8-3105f85a1f28", "type": "concept", "title": "Feasible intervals and boundary conditions"}, {"id": "85060a17-c468-4819-aef1-8638fe9322dc", "type": "concept", "title": "Candidate generation and comparison"}], "description": "Turn a narrative choice into an objective function and feasible domain."}, {"id": "c77fb33a-2449-4cdf-97d8-a51a8a1f01b1", "type": "subtopic", "title": "First- and second-order conditions", "children": [{"id": "fd54d1e4-31f0-48c3-80f8-f4754099fc9f", "type": "concept", "title": "Critical points and stationary points"}, {"id": "f517b2bb-6cc4-4e64-a7f9-45badd271231", "type": "concept", "title": "First-derivative sign tests"}, {"id": "4be27da4-53bb-4008-af6b-1183b3dfa352", "type": "concept", "title": "Second-derivative and concavity tests"}], "description": "Use derivatives to locate and classify optima."}, {"id": "3c7b3914-f4c0-43ee-8f7d-6859524fefe2", "type": "subtopic", "title": "Business applications", "children": [{"id": "7e4eb575-21d3-4457-9e75-3dc207f093ba", "type": "concept", "title": "Profit maximization and cost minimization"}, {"id": "33e8b84f-9123-45fe-b7f1-249f41d17121", "type": "concept", "title": "Optimal price, output, advertising, and order size"}, {"id": "2eb6849d-4592-48fc-a83f-751a03b2bdd3", "type": "concept", "title": "Break-even versus optimum"}], "description": "Apply optimization to recurring managerial problems."}, {"id": "885ba66a-4162-4cb0-b58e-7581c94755ed", "type": "subtopic", "title": "Robustness", "children": [{"id": "c8d7c113-c80e-4991-b17e-d0dde63ae49d", "type": "concept", "title": "Boundary solutions and flat optima"}, {"id": "10f1f1c1-b8c3-4090-b185-c16ffdb1315e", "type": "concept", "title": "Sensitivity tables and scenario ranges"}, {"id": "bbe2e813-ccf6-4b17-b972-fde167beb7fd", "type": "concept", "title": "Implementation constraints and managerial judgment"}], "description": "Test whether the recommended decision survives imperfect assumptions."}]}, {"id": "1093117a-9145-4acc-aef6-aad2d8ae53e4", "type": "topic", "title": "Exponential Growth, Logarithms, and Financial Applications", "description": "Explains compounding, discounting, growth, decay, and scale effects that appear throughout finance, strategy, marketing, and operations.", "children": [{"id": "1c08c13b-894b-4191-adec-e265dcd7d53e", "type": "subtopic", "title": "Exponential models", "children": [{"id": "5e51dd6a-95ae-4a26-bedb-aa5aeef7a300", "type": "concept", "title": "Discrete and continuous growth"}, {"id": "a9241928-c0fa-4ee3-9c6a-ca28163a4b6c", "type": "concept", "title": "Growth and decay constants"}, {"id": "187adce2-5472-4faa-a249-361f2ab59858", "type": "concept", "title": "Doubling time and half-life"}], "description": "Model processes whose change is proportional to their current level."}, {"id": "4cd03758-9f0e-40b2-9191-39688c1f6051", "type": "subtopic", "title": "Logarithms", "children": [{"id": "faea178f-0496-4092-8f83-3d023a6afae4", "type": "concept", "title": "Log laws and inverse relationships"}, {"id": "ca14af9b-0782-4894-af21-69a2505a2a5a", "type": "concept", "title": "Semi-log and log-log interpretation"}, {"id": "f5aab160-a3d0-4662-aacd-f361051617d9", "type": "concept", "title": "Growth-rate approximation"}], "description": "Use logarithms to solve for time, rates, and elasticities."}, {"id": "95d0b3d7-5559-4426-bf7d-86808cf86ebe", "type": "subtopic", "title": "Time value of money", "children": [{"id": "e135d344-b62d-4981-8b5c-70b626996242", "type": "concept", "title": "Present and future value"}, {"id": "4776a787-157d-4e94-a4dd-2bfd4a42dfbc", "type": "concept", "title": "Effective versus nominal rates and continuous compounding"}, {"id": "59f4ba49-0122-4e94-92a2-171b88b3e1b5", "type": "concept", "title": "Net present value and internal-rate intuition"}], "description": "Compare cash flows occurring at different dates."}, {"id": "e16a175e-0a0f-461e-9955-7cd532718ceb", "type": "subtopic", "title": "Growth realism", "children": [{"id": "d926488d-3f8a-40d5-822b-6e8de1ecd35d", "type": "concept", "title": "Saturation and logistic alternatives"}, {"id": "661791ae-bed2-4901-8755-539fba171bc8", "type": "concept", "title": "Inflation and real growth"}, {"id": "15fd2f70-3fc1-44e1-adb1-7c30cccd64d1", "type": "concept", "title": "Forecast horizons and structural breaks"}], "description": "Know when exponential extrapolation becomes implausible."}]}, {"id": "ff287aea-7207-4243-900b-6a55ae3b9de9", "type": "topic", "title": "Integration and Accumulation", "description": "Treats integration as the aggregation of continuously changing marginal quantities. It connects rates to totals and supports consumer surplus, inventory flow, revenue accumulation, and continuous cash-flow analysis.", "children": [{"id": "8b753338-6ce6-416e-87f0-f8e15d0a6b60", "type": "subtopic", "title": "Antiderivatives", "children": [{"id": "e4265869-2e68-434c-8c1b-c987fc4eeef5", "type": "concept", "title": "Indefinite integrals and constants of integration"}, {"id": "6e6d1cd7-910f-49e0-81c1-95e1ea815f23", "type": "concept", "title": "Basic power, exponential, and logarithmic forms"}, {"id": "afbf4ffa-1e08-453f-9ac1-d5c378da6399", "type": "concept", "title": "Initial conditions"}], "description": "Reverse differentiation and recover totals from marginal functions."}, {"id": "e032511c-952b-4cbc-96c3-53bf896b8616", "type": "subtopic", "title": "Definite integrals", "children": [{"id": "d5921eb6-d6d0-49d3-ad56-25d841b96f90", "type": "concept", "title": "Riemann-sum intuition"}, {"id": "e3ec94ef-756b-4f01-ac3d-933b18a99486", "type": "concept", "title": "Net versus total area"}, {"id": "34735146-f72a-4104-9c47-f9bf5d182105", "type": "concept", "title": "Units of an integral"}], "description": "Interpret accumulated quantity and signed area over an interval."}, {"id": "30541966-4689-4555-aafb-d8fa206eac85", "type": "subtopic", "title": "Fundamental Theorem of Calculus", "children": [{"id": "1c977b9c-3c0d-4e0e-885d-47c1befff25d", "type": "concept", "title": "Evaluation by antiderivatives"}, {"id": "171d2473-fc40-4565-94c9-f09722006599", "type": "concept", "title": "Variable upper limits"}, {"id": "6e576cfd-5d88-40c5-b332-18c2bbc5ef05", "type": "concept", "title": "Interpretation rather than mechanical substitution"}], "description": "Connect accumulation functions and instantaneous rates."}, {"id": "0b003428-08a5-4a84-a630-76fc99bffe89", "type": "subtopic", "title": "Business applications", "children": [{"id": "39828ce6-8ede-493a-9c41-356b50159363", "type": "concept", "title": "Total cost from marginal cost"}, {"id": "f662979c-9304-4023-b895-186799e97083", "type": "concept", "title": "Consumer and producer surplus"}, {"id": "d189d8aa-dcee-45a6-9e66-6ce1c1ecdebe", "type": "concept", "title": "Continuous cash flow, inventory, and learning accumulation"}], "description": "Aggregate changing rates into decision-relevant totals."}]}, {"id": "e7759ff2-2f09-47c4-828e-ab630f548712", "type": "topic", "title": "Multivariable Functions and Partial Derivatives", "description": "Extends the course from one-driver models to realistic business outcomes influenced by price, advertising, labor, capital, and other inputs simultaneously.", "children": [{"id": "d2149bb2-7b66-4be4-b6e9-91215c436eea", "type": "subtopic", "title": "Multivariable representation", "children": [{"id": "cdce633f-063d-4627-9530-610b73214433", "type": "concept", "title": "Surfaces, contours, and level curves"}, {"id": "b13fdbe8-fe8c-4624-ae74-2f2fd03149f3", "type": "concept", "title": "Domains and feasible regions"}, {"id": "2598f796-119f-4544-bc04-a3e603ae86c9", "type": "concept", "title": "Cobb–Douglas and response-surface examples"}], "description": "Describe outputs determined by several inputs."}, {"id": "8de2d830-c860-4402-9fb0-9c26b61bec8b", "type": "subtopic", "title": "Partial derivatives", "children": [{"id": "2f442712-2b17-4535-968c-f9bb3091fb88", "type": "concept", "title": "First and second partial derivatives"}, {"id": "7f10f5ec-37b9-46de-8a2d-00875cb7ccdc", "type": "concept", "title": "Own and cross effects"}, {"id": "6fddb76e-ff4f-4041-b905-e4c9eda182c8", "type": "concept", "title": "Units and ceteris paribus interpretation"}], "description": "Measure one local effect while holding other inputs fixed."}, {"id": "4bd23337-9f1e-4760-bf48-2125e800eb9f", "type": "subtopic", "title": "Gradient and directional change", "children": [{"id": "d30225d2-d5ee-4553-844f-55f2493b9851", "type": "concept", "title": "Gradient vectors"}, {"id": "58848cdc-5a41-425b-8b7a-470470c998a8", "type": "concept", "title": "Directional derivatives"}, {"id": "17803de6-cb33-44d5-9a0f-d9bd1ba50f1e", "type": "concept", "title": "Tangent-plane approximation"}], "description": "Identify the direction of steepest local improvement."}, {"id": "0c2fb66e-2563-4489-acda-788d176cd165", "type": "subtopic", "title": "Interaction and complementarity", "children": [{"id": "2479e070-2107-4fe8-a17c-5fb41ebd7bc3", "type": "concept", "title": "Cross-partials"}, {"id": "4b343d9d-aa98-42c9-9a88-62be77d5891a", "type": "concept", "title": "Complements and substitutes"}, {"id": "8b41c45b-59ce-4599-868b-cb0f6599c39a", "type": "concept", "title": "Scale, returns, and synergy claims"}], "description": "Understand when the effect of one input depends on another."}]}, {"id": "4241f67f-bb1c-499b-a76b-260f143a65b8", "type": "topic", "title": "Constrained Optimization and Lagrange Multipliers", "description": "Addresses decisions made under budgets, capacity, policy, or resource constraints. The multiplier provides both a solution technique and an economic interpretation of scarce-resource value.", "children": [{"id": "27bd6aa1-62f2-4c6c-a45d-3a868fde0a5b", "type": "subtopic", "title": "Constraint geometry", "children": [{"id": "34b3b3d3-2b3a-44b7-9883-c0aa9bfd54ba", "type": "concept", "title": "Equality and inequality constraints"}, {"id": "c8858683-896d-4481-a444-73300cfbd9d7", "type": "concept", "title": "Binding versus slack constraints"}, {"id": "98a041da-47f6-446a-a555-b9c3eb6c1ba0", "type": "concept", "title": "Feasibility and boundary solutions"}], "description": "See feasible choices as curves, surfaces, or regions."}, {"id": "3915d88b-5728-4108-a58b-2563cf2fc6eb", "type": "subtopic", "title": "Lagrange method", "children": [{"id": "d880d4f6-abd5-4238-a1fc-d52b8faa5fa6", "type": "concept", "title": "Lagrangian construction"}, {"id": "aa91dab0-6340-4a86-90b0-72ad35c5cf11", "type": "concept", "title": "First-order conditions"}, {"id": "3c3d1079-56e5-47d4-aec9-75e728b70556", "type": "concept", "title": "Second-order and candidate checks"}], "description": "Solve smooth equality-constrained problems."}, {"id": "a05ecb6b-8320-49a5-950b-acec4cc27fb2", "type": "subtopic", "title": "Shadow prices", "children": [{"id": "0b8bec1e-cb33-4506-95e5-dd1efe0410d3", "type": "concept", "title": "Marginal value of budget or capacity"}, {"id": "241f001b-5fcb-4279-a871-011341b52bdd", "type": "concept", "title": "Units and sign conventions"}, {"id": "52a6005c-4d32-4ec2-a28e-cd933db2bf8b", "type": "concept", "title": "Local sensitivity limits"}], "description": "Interpret the multiplier as the local value of relaxing a constraint."}, {"id": "ec26fe3e-4fa9-47e5-b809-1de6bf800f92", "type": "subtopic", "title": "Business applications", "children": [{"id": "888f7fdc-36ea-4b24-bc1f-15fa8727f712", "type": "concept", "title": "Product mix and capacity"}, {"id": "2a23faa4-1c5a-4ca8-a210-8842b34d428e", "type": "concept", "title": "Marketing-budget allocation"}, {"id": "e9f6bf09-fd50-419a-bf1c-e8fe1692d5ff", "type": "concept", "title": "Cost minimization and utility maximization"}], "description": "Allocate scarce resources across competing uses."}]}, {"id": "5561daed-e9ed-4e5d-a8ca-8fdb075dd949", "type": "topic", "title": "Matrix Algebra and Systems of Equations", "description": "Provides compact tools for interdependent equations, portfolios, input–output systems, regressions, and scenario models. The emphasis is on structure, interpretation, and computational reliability.", "children": [{"id": "568acfc5-0882-458b-acf0-cd6d152d9822", "type": "subtopic", "title": "Matrix foundations", "children": [{"id": "7df1383f-00f0-43da-876b-074e53acdda4", "type": "concept", "title": "Vectors, matrices, dimensions, and indexing"}, {"id": "643adf0a-c8a3-4684-86ab-0008803dad63", "type": "concept", "title": "Addition, scalar multiplication, and matrix products"}, {"id": "b0bd6d4c-9bdf-4c98-9fdf-789f64771f91", "type": "concept", "title": "Identity, transpose, and inverse"}], "description": "Represent many related quantities in a disciplined form."}, {"id": "e059549d-cd3b-4440-a8c8-c2810ce067f5", "type": "subtopic", "title": "Linear systems", "children": [{"id": "2813b382-dc81-4631-a583-22efd9da9667", "type": "concept", "title": "Substitution, elimination, and row reduction"}, {"id": "51999d1b-9b47-4b28-a0b6-5c991d6bcf40", "type": "concept", "title": "Rank, uniqueness, and inconsistency"}, {"id": "d100d459-c31a-493c-aaba-ae2e18814747", "type": "concept", "title": "Ill-conditioning and numerical stability"}], "description": "Solve simultaneous relationships and assess whether solutions are meaningful."}, {"id": "068327fb-9882-4570-a74b-fec6d784d2e2", "type": "subtopic", "title": "Business uses", "children": [{"id": "de0675e3-56c9-48cf-bb21-bcadb5a1b927", "type": "concept", "title": "Input–output and network models"}, {"id": "3b2cb5af-9e03-4d1b-9ce5-5dd9d51b38bd", "type": "concept", "title": "Portfolio weights and scenario payoffs"}, {"id": "ab70efb3-549e-48e6-8196-1bd12826856d", "type": "concept", "title": "Markov transition and customer-migration matrices"}], "description": "Apply matrix structure to common managerial settings."}, {"id": "7a2b9dba-4ea1-448e-bee7-c5fc041cee9e", "type": "subtopic", "title": "Spreadsheet implementation", "children": [{"id": "2949ba06-33fb-4845-96bc-327291a99b89", "type": "concept", "title": "Named ranges and matrix functions"}, {"id": "05022dca-8e05-4bfb-8df3-6f6d89c033cf", "type": "concept", "title": "Formula tracing and reconciliation"}, {"id": "db0f3fc1-f662-4a34-94ef-c9d67ffce33b", "type": "concept", "title": "Documentation and error checks"}], "description": "Build formulas that remain auditable as assumptions change."}]}, {"id": "b14381de-e117-41f6-9796-b0e69dc48d1d", "type": "topic", "title": "Linear Programming and Optimization Models", "description": "Introduces prescriptive analytics for allocating limited resources among competing activities. Students formulate models, solve graphically and computationally, and interpret sensitivity information.", "children": [{"id": "ba9d5682-5802-4161-b738-f5fe887aacb4", "type": "subtopic", "title": "Model formulation", "children": [{"id": "c4d02f96-fa66-4683-8efe-2396eb6fbae3", "type": "concept", "title": "Decision variables and sign restrictions"}, {"id": "e065b8d9-d510-4b17-924a-a0f5b0ee4ee0", "type": "concept", "title": "Objective coefficients"}, {"id": "d8dac6cc-d354-4666-8c8e-470264867153", "type": "concept", "title": "Resource, demand, balance, and logical constraints"}], "description": "Express a decision as variables, objective, and linear constraints."}, {"id": "135da43d-9637-407f-92b4-d32afabf75ee", "type": "subtopic", "title": "Geometry and solution", "children": [{"id": "e18ce9cc-33e4-454a-bcd3-9647472489eb", "type": "concept", "title": "Feasible region"}, {"id": "21b9c329-106c-4a00-8116-95dab4125ee0", "type": "concept", "title": "Corner-point method"}, {"id": "b16fcf93-ed7e-4013-9524-f3da3efcf2ea", "type": "concept", "title": "Infeasibility, unboundedness, and multiple optima"}], "description": "Understand why an optimum occurs at an extreme point."}, {"id": "e46325ec-887a-4831-bdb6-82b40e84e508", "type": "subtopic", "title": "Solver implementation", "children": [{"id": "8b16d13a-bfab-4bb4-b91b-3ce84236ffc1", "type": "concept", "title": "Solver setup and model separation"}, {"id": "31ec5c8e-dfe2-4cc4-8653-88c2838d4c3e", "type": "concept", "title": "Constraint checks and solution verification"}, {"id": "c7463c84-fc4b-4a76-9548-a4f8f88dfe14", "type": "concept", "title": "Integer and binary extensions as enrichment"}], "description": "Use spreadsheet optimization without treating it as a black box."}, {"id": "33b198dc-a6e5-46f2-9d71-8b150d9670ad", "type": "subtopic", "title": "Sensitivity and dual interpretation", "children": [{"id": "4156ff25-a3d1-4a16-b4cd-4750c2864c03", "type": "concept", "title": "Slack and binding constraints"}, {"id": "5e393918-c3ac-4694-97d3-cb17d9be47c6", "type": "concept", "title": "Shadow prices and reduced costs"}, {"id": "52165e5f-d904-4cbf-9da3-b0673493117e", "type": "concept", "title": "Allowable ranges and re-optimization"}], "description": "Explain how coefficient or resource changes affect the recommendation."}]}, {"id": "b4971741-9461-4a9e-a1b9-24717ff44a1a", "type": "topic", "title": "Uncertainty, Sensitivity, and Scenario Analysis", "description": "Builds the habit of reporting a range of defensible outcomes rather than a single fragile answer. This unit connects deterministic models to risk-aware decision-making without replacing a later statistics course.", "children": [{"id": "e192eac7-02c6-47ed-bfb7-785c898195b8", "type": "subtopic", "title": "Sensitivity analysis", "children": [{"id": "566ad99f-a017-41c4-a344-4aae371b21ef", "type": "concept", "title": "One-way and two-way data tables"}, {"id": "826d1e33-bc3b-4b44-950c-263f32156609", "type": "concept", "title": "Tornado charts and elasticities"}, {"id": "a25e66dd-6a76-4c46-b0e5-2e95fe81aaec", "type": "concept", "title": "Local versus global sensitivity"}], "description": "Determine which assumptions actually drive the output."}, {"id": "cd1fb4d3-200d-4196-9323-13268570808d", "type": "subtopic", "title": "Scenario analysis", "children": [{"id": "09ac0ed6-1200-41cf-bf2f-de1c7a11fb97", "type": "concept", "title": "Base, upside, downside, and stress scenarios"}, {"id": "549fbdc2-79b5-4160-bec7-f151696c3800", "type": "concept", "title": "Correlated assumption sets"}, {"id": "788e7f71-fe88-40df-93a0-00b57cf41067", "type": "concept", "title": "Triggers, contingencies, and decision rules"}], "description": "Construct coherent alternative futures."}, {"id": "31eafff7-5e9f-4e88-af19-e1c262a53baa", "type": "subtopic", "title": "Uncertainty basics", "children": [{"id": "ac882931-33ad-4904-a8ed-65a33a2e9d05", "type": "concept", "title": "Expected value and weighted scenarios"}, {"id": "f6a8f2f6-c9f6-4830-b56b-23909eb7645a", "type": "concept", "title": "Range, variance intuition, and downside risk"}, {"id": "7e7461c2-3c21-4723-9a1b-977a2ea37c28", "type": "concept", "title": "Monte Carlo simulation as an extension"}], "description": "Represent uncertain inputs at an introductory level."}, {"id": "dec34f95-253e-4f99-9e87-9e0b46dc96e7", "type": "subtopic", "title": "Robust decisions", "children": [{"id": "d589715e-e206-4baf-abc2-e45bb629680f", "type": "concept", "title": "Regret and break-even thresholds"}, {"id": "d19be8d4-4c60-4314-98d2-13e57bdcc50f", "type": "concept", "title": "Safety margins and real options intuition"}, {"id": "ed5541a1-1004-45a7-a619-59378bbbf467", "type": "concept", "title": "Model risk and stress testing"}], "description": "Prefer choices that perform acceptably across plausible conditions."}]}, {"id": "7e6b8859-548e-4d23-bf5d-b2043e2bc2d4", "type": "topic", "title": "Computational Tools, Visualization, and Executive Communication", "description": "Integrates spreadsheet modeling, graphing, reproducibility, and concise communication. Students must be able to defend how a result was produced and what decision it does—and does not—support.", "children": [{"id": "2675beee-ac00-4664-a417-a41b307c3b81", "type": "subtopic", "title": "Spreadsheet engineering", "children": [{"id": "3ef4dde0-296a-48bc-8dd3-54eeb9b9b1a3", "type": "concept", "title": "Cell references, named inputs, and formula consistency"}, {"id": "6a880874-0662-4c71-a2af-39e1ae78cded", "type": "concept", "title": "Audit checks, versioning, and change logs"}, {"id": "8089bd8b-8dea-41f5-a543-b716ace45033", "type": "concept", "title": "Goal Seek, data tables, and Solver"}], "description": "Separate assumptions, calculations, checks, and outputs."}, {"id": "522ae774-ef33-4566-b1a5-4371db85f01d", "type": "subtopic", "title": "Visualization", "children": [{"id": "0ab6ba42-6b6b-4b59-9b7a-f95ab80902cd", "type": "concept", "title": "Function and marginal plots"}, {"id": "3177944d-aaa4-4c22-8032-244467587819", "type": "concept", "title": "Contour plots and feasible regions"}, {"id": "d752f78c-5919-4ff9-9e7c-ec0d9657028c", "type": "concept", "title": "Sensitivity charts and uncertainty displays"}], "description": "Choose displays that reveal relationships without distorting them."}, {"id": "d458b8b6-8403-4478-b530-8aef6adf8623", "type": "subtopic", "title": "Executive interpretation", "children": [{"id": "4ffe017a-9397-43dd-b02e-bd2b9cffd6ed", "type": "concept", "title": "Decision, evidence, assumptions, and risks"}, {"id": "1d422a8a-578e-46d1-a25c-d7388ede3181", "type": "concept", "title": "Units, magnitude, and practical significance"}, {"id": "ff79e22c-8107-41e8-ba20-3b80c5511f87", "type": "concept", "title": "Concise memo and presentation structure"}], "description": "Translate mathematics into an actionable recommendation."}, {"id": "3f8ba869-2a1f-4955-ad36-5bc3abc31ff8", "type": "subtopic", "title": "Governance and AI-assisted analysis", "children": [{"id": "939950b8-8dfe-47d1-bde9-545178fe11a8", "type": "concept", "title": "Independent verification of generated formulas"}, {"id": "8df03e0e-17a1-40cd-8354-a46a930a2b4e", "type": "concept", "title": "Data confidentiality and provenance"}, {"id": "338d9c77-c0f1-4819-bc78-8953535219cd", "type": "concept", "title": "Disclosure, reproducibility, and human responsibility"}], "description": "Use automation while preserving accountability."}]}], "dbBacked": true}$cqmjson$::jsonb,
